from collections import deque
import heapq

class NetworkSimplex:
    def __init__(self, n_orig, arc_tuples, big_cost=10**35, inf_cap=10**9):
        # arc_tuples list (u,v,lo,hi,cost), all nodes 0..n_orig-1
        self.n_orig=n_orig
        self.root=n_orig
        self.N=n_orig+1
        self.big=big_cost
        self.inf=inf_cap
        self.fr=[]; self.to=[]; self.lo=[]; self.hi=[]; self.cost=[]; self.flow=[]; self.basic=[]
        for u,v,l,h,c in arc_tuples:
            if not (0<=u<n_orig and 0<=v<n_orig): raise ValueError('node')
            if l<0 or h<l: raise ValueError('bounds')
            self.add_arc(u,v,l,h,c)
        self.n_real=len(self.fr)
        # artificial both directions per original node
        self.art_root=[]; self.art_to_root=[]
        for v in range(n_orig):
            self.art_root.append(self.add_arc(self.root,v,0,inf_cap,big_cost))
            self.art_to_root.append(self.add_arc(v,self.root,0,inf_cap,big_cost))
        # tree adj
        self.tadj=[[] for _ in range(self.N)]
        bal=[0]*n_orig
        for i in range(self.n_real):
            bal[self.fr[i]]-=self.lo[i]
            bal[self.to[i]]+=self.lo[i]
        # choose initial art arcs
        for v,b in enumerate(bal):
            if b>0: # out-in >0, need artificial inflow root->v
                eid=self.art_root[v]; self.flow[eid]=b
            elif b<0:
                eid=self.art_to_root[v]; self.flow[eid]=-b
            else:
                eid=self.art_root[v]; self.flow[eid]=0
            self.basic[eid]=1
            self.tadj[self.root].append(eid); self.tadj[v].append(eid)
        # root conservation check optional
        # all real at lo, artificial flows satisfy
        self.iters=0; self.bound_flips=0
        self.max_iters=1000000

    def add_arc(self,u,v,l,h,c):
        eid=len(self.fr)
        self.fr.append(u); self.to.append(v); self.lo.append(l); self.hi.append(h); self.cost.append(c)
        self.flow.append(l); self.basic.append(0)
        return eid

    def potentials(self):
        N=self.N
        pi=[None]*N
        pi[self.root]=0
        dq=deque([self.root])
        while dq:
            u=dq.popleft()
            pu=pi[u]
            for eid in self.tadj[u]:
                a=self.fr[eid]; b=self.to[eid]
                if a==u:
                    if pi[b] is None:
                        pi[b]=pu+self.cost[eid]; dq.append(b)
                elif b==u:
                    if pi[a] is None:
                        pi[a]=pu-self.cost[eid]; dq.append(a)
                else:
                    raise RuntimeError('bad tree arc')
        if any(x is None for x in pi):
            raise RuntimeError('disconnected tree')
        return pi

    def find_path(self,start,target):
        N=self.N; par=[-2]*N; pare=[-1]*N
        par[start]=-1; dq=deque([start])
        while dq:
            u=dq.popleft()
            if u==target: break
            for eid in self.tadj[u]:
                a=self.fr[eid]; b=self.to[eid]
                v=b if a==u else a if b==u else -1
                if v<0: raise RuntimeError('bad tree')
                if par[v]==-2:
                    par[v]=u; pare[v]=eid; dq.append(v)
        if par[target]==-2: raise RuntimeError('no tree path')
        path=[]; cur=target
        while cur!=start:
            path.append(pare[cur]); cur=par[cur]
        path.reverse()
        return path

    def solve(self, prefer_bland=True, verbose=False):
        n_real=self.n_real; N=self.N
        while True:
            self.iters+=1
            if self.iters>self.max_iters: raise RuntimeError('iteration limit')
            pi=self.potentials()
            enter=-1; enter_dir=0; enter_rc=0
            # Bland: smallest arc index with violation
            for eid in range(len(self.fr)):
                if self.basic[eid]: continue
                l=self.lo[eid]; h=self.hi[eid]
                if h<=l: continue
                x=self.flow[eid]
                rc=self.cost[eid]+pi[self.fr[eid]]-pi[self.to[eid]]
                if x==l:
                    if rc<0:
                        enter=eid; enter_dir=1; enter_rc=rc; break
                elif x==h:
                    if rc>0:
                        enter=eid; enter_dir=-1; enter_rc=rc; break
                else:
                    raise RuntimeError('nonbasic interior flow')
            if enter<0:
                # verify no violations
                return True
            u=self.fr[enter]; v=self.to[enter]; alpha=enter_dir
            start,end=(u,v) if alpha==1 else (v,u)
            path=self.find_path(start,end)
            theta=(self.hi[enter]-self.flow[enter]) if alpha==1 else (self.flow[enter]-self.lo[enter])
            leave=-1; leave_theta=theta
            for eid in path:
                a=self.fr[eid]; b=self.to[eid]
                # orientation along traversal start->end; path order corresponds traversal
                # determine by checking path adjacent order using flows? Use path nodes not stored; infer relative to current sequence.
                # We need know direction. find_path only arcs order; first arc incident start, alternate.
                # We'll track current node separately below.
                pass
            # redo with current node
            cur=start
            theta=(self.hi[enter]-self.flow[enter]) if alpha==1 else (self.flow[enter]-self.lo[enter])
            leave=-1
            path_dirs=[]
            for eid in path:
                a=self.fr[eid]; b=self.to[eid]
                if a==cur:
                    nxt=b; forward=True
                elif b==cur:
                    nxt=a; forward=False
                else: raise RuntimeError('path direction bad')
                res=(self.hi[eid]-self.flow[eid]) if forward else (self.flow[eid]-self.lo[eid])
                path_dirs.append(forward)
                if res<theta:
                    theta=res; leave=eid
                elif res==theta:
                    if leave<0 or eid<leave:
                        leave=eid
                cur=nxt
            if cur!=end: raise RuntimeError('path end bad')
            # if no tree arc at theta, entering bound flips; if tree exists at theta, choose tree (unless Bland favors entering? use tree)
            # update flows along path by theta in traversal direction
            if theta:
                cur=start
                for eid,forward in zip(path,path_dirs):
                    if forward: self.flow[eid]+=theta
                    else: self.flow[eid]-=theta
                self.flow[enter]+=alpha*theta
            # if leave tree
            if leave>=0:
                # remove leave
                self.basic[leave]=0
                a=self.fr[leave]; b=self.to[leave]
                try: self.tadj[a].remove(leave)
                except ValueError: pass
                try: self.tadj[b].remove(leave)
                except ValueError: pass
                # add enter
                self.basic[enter]=1
                self.tadj[u].append(enter); self.tadj[v].append(enter)
            else:
                # entering hit own bound, remains nonbasic
                self.bound_flips+=1
            if verbose and self.iters%1000==0:
                print('iter',self.iters,'enter',enter,'theta',theta,'leave',leave,file=__import__('sys').stderr)

    def objective(self):
        return sum(self.cost[i]*self.flow[i] for i in range(self.n_real))
